import { useCallback, useEffect, useState } from 'react';

import { finUUID } from '@common/utils/env';
import LocalStorageKey from '@common/utils/local-storage-key';
import { createLogger } from '@common/utils/logger';

const logger = createLogger('storage-proxy-window');

const PERMITTED_KEYS = [
    LocalStorageKey.ThemePaletteSheet,
    LocalStorageKey.ThemePaletteDefaultScheme,
    LocalStorageKey.SelectedColorScheme
];

const StorageProxy = () => {
    const [channelLoadInitialised, setChannelLoadInitialise] = useState(false);

    const initialiseChannel = useCallback(async () => {
        const providerWindow = { uuid: fin.me.uuid, name: fin.me.uuid };
        if (!channelLoadInitialised) {
            const channelName = `channel-${fin.me.name}`;
            setChannelLoadInitialise(true);
            logger.debug('initialiseChannel', `Creating channel ${channelName}`);
            const channel = await fin.InterApplicationBus.Channel.create(channelName);
            channel.onConnection(async (connection) => {
                const { uuid, name } = connection;
                if (uuid !== providerWindow.uuid && name !== providerWindow.name) {
                    throw new Error('Only the platform provider can use storage proxy.');
                }
                // Prevents multiple proxy windows when the provider reloads during dev mode.
                await fin.Window.wrapSync(connection).addListener('reloaded', () =>
                    fin.Window.getCurrentSync().close()
                );
            });

            channel.register('setItem', ({ value, key }: { value: string; key: LocalStorageKey }) => {
                if (PERMITTED_KEYS.includes(key)) {
                    localStorage.setItem(`${finUUID}-${key}`, value);
                } else {
                    throw new Error(`Storage key ${key} is not permitted to be written to`);
                }
            });
        }
    }, [channelLoadInitialised]);

    useEffect(() => {
        initialiseChannel();
    }, [initialiseChannel]);

    return <></>;
};

export default StorageProxy;
